define(['core/ajax', 'core/notification'], function(Ajax, Notification) {

    var init = function(blockid) {
        var root     = document.getElementById('block-iomad-claude-' + blockid);
        var textarea = root.querySelector('.claude-question');
        var button   = root.querySelector('.claude-submit');
        var response = root.querySelector('.claude-response');

        var ask = function() {
            var question = textarea.value.trim();
            if (!question) {
                return;
            }

            button.disabled = true;
            response.textContent = 'Thinking…';
            response.className = 'claude-response mt-3 text-muted';

            Ajax.call([{
                methodname: 'block_iomad_claude_ask',
                args: {question: question},
            }])[0].then(function(answer) {
                response.textContent = answer;
                response.className = 'claude-response mt-3';
                button.disabled = false;
                return answer;
            }).catch(function(e) {
                response.textContent = '';
                button.disabled = false;
                Notification.exception(e);
            });
        };

        button.addEventListener('click', ask);

        textarea.addEventListener('keydown', function(e) {
            if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
                ask();
            }
        });
    };

    return {
        init: init,
    };
});
